import{_ as t,o,c as n,a3 as s}from"./chunks/framework.iKZ1V-y0.js";const u=JSON.parse('{"title":"Offline Slowdown and Possible Remedies (Fixed)","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"下线降速现象与相关补救方法探究（已被修复）","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-XnpxncxXlSmIhlbhisNQ8d.md","filePath":"logistics/src/page-XnpxncxXlSmIhlbhisNQ8d.md","lastUpdated":null}'),l={name:"logistics/src/page-XnpxncxXlSmIhlbhisNQ8d.md"};function i(a,e,r,d,p,c){return o(),n("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="下线降速现象与相关补救方法探究-已被修复" aria-hidden="true"></span><h1 id="offline-slowdown-and-possible-remedies-fixed" tabindex="-1">Offline Slowdown and Possible Remedies (Fixed) <a class="header-anchor" href="#offline-slowdown-and-possible-remedies-fixed" aria-label="Permalink to &quot;Offline Slowdown and Possible Remedies (Fixed)&quot;">​</a></h1><blockquote><p>Source page ID: <code>XnpxncxXlSmIhlbhisNQ8d</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Known observations: belt speed fluctuates offline approximately every 5 minutes, for a total fluctuation duration below 4s. Belts and filtering/counting control ports may fluctuate simultaneously offline. Reports disagree on the resulting slowdown and may differ by player.</p><p>Reducing belts to half rate sometimes alleviates offline slowdown, apparently without eliminating it; there is no unified conclusion.</p><p>Currently, any logistics route containing a belt is thought to slow to that belt&#39;s speed when its speed fluctuates.</p><p>Nonmember 乾震 proposed compensating power with a differential structure: belt–control port&gt;0.5–belt. Belts and control ports can therefore provide the required rate difference.</p><p>Later tests found that merging two half-duty-cycle belts can slow down or block items. Consider this when reducing or eliminating offline slowdown.</p><p>Some tests support equal offline slowdown for belts and control ports.</p><p>Some experiments suggest non-full-rate belts may be unaffected by offline slowdown.</p></div>',1)])])}const m=t(l,[["render",i]]);export{u as __pageData,m as default};
